func CheckoutPrice(order domain.Order) int64 {
	if order.Premium && order.Total >= 1000 {
		return order.Total - order.Total/10
	}
	return order.Total
}

func QuotePrice(order domain.Order) int64 {
	if order.Premium && order.Total >= 1000 {
		return order.Total * 90 / 100
	}
	return order.Total
}

type Order struct {
	Total   int64
	Premium bool
}
